triggers.TRIGGER_BODY:
DECLARE
V_NAM VARCHAR2(200);
d_status varchar2(50);
BEGIN
if  inserting  then
if  :new.cp_id = :new.cp_id  then
SELECT FUN_SUPPLIER_NAME(:NEW.CP_INV_REF) INTO V_NAM FROM DUAL;
 INSERT INTO CAR_LEDGER(CL_CAR_TYPE,CL_MODEL,CL_PANEL,CL_COLOR,CL_DATE_IN,CL_PURCH_PRICE,CL_CAR_NOTE,CL_SUPPLIER,cl_cp_id,cl_purch_status,CL_SALES_STATUS,CL_INVOICE_NO,CL_HIKL) VALUES(:NEW.CP_TYPE,:NEW.CP_MODEL,:NEW.CP_PANEL,:NEW.CP_COLOR,:NEW.CP_DATE_IN,:NEW.CP_PURCH_PRICE,:NEW.CP_CAR_NOTE,V_NAM,:new.cp_id,'yes','no',:new.cp_inv_ref,:new.cp_hikl);
 end if;
 end if;
 if deleting then
 if :old.cp_id=:old.cp_id then
 select cl_sales_status into d_status from car_ledger where cl_cp_id=:old.cp_id;
 if d_status='yes' then
 d_status:=null;
 else
 delete from CAR_LEDGER where cl_cp_id=:old.cp_id;
 end if;
end if;
end if;
 END;

declare
d_status varchar2(50);
BEGIN

 if :old.cp_id=:old.cp_id then
 select cl_sales_status into d_status from car_ledger where cl_cp_id=:old.cp_id;
 if d_status='yes' then
 d_status:=null;
 else
 delete from CAR_PURCHASE where cp_id=:old.cp_id;
 delete from CAR_LEDGER where cl_cp_id=:old.cp_id;
end if;
end if;
END;

declare
dd number;
dc number;
BEGIN
  IF INSERTING THEN
  IF :NEW.cp_ID=:NEW.cp_ID THEN
select nvl(pui_total,0) into dd from purchase_invoice where pui_id=:new.cp_inv_ref;
update purchase_invoice set pui_total=dd+:new.cp_purch_price where pui_id=:new.cp_inv_ref;
  END IF;
  END IF;
  IF UPDATING THEN

 select nvl(pui_total,0) into dd from purchase_invoice where pui_id=:new.cp_inv_ref;
 dc:=dd-:old.cp_purch_price;
update purchase_invoice set pui_total=dc+:new.cp_purch_price where pui_id=:new.cp_inv_ref;

  END IF;
  IF DELETING THEN
  if  :old.cp_id = :old.cp_id  then
select nvl(pui_total,0) into dd from purchase_invoice where pui_id=:old.cp_inv_ref;
update purchase_invoice set pui_total=dd-:old.cp_purch_price where pui_id=:old.cp_inv_ref;


end  if  ;
end  if;
END;

DECLARE
S_NUM NUMBER;
S_ACT_NAME VARCHAR2(300);
S_BAR_NUM NUMBER;
S_MAIN_NUM NUMBER;
M_NUM NUMBER;
M_ACT_NAME VARCHAR2(300);
M_BAR_NUM NUMBER;
M_MAIN_NUM NUMBER;
BEGIN
SELECT AC_NUM,BAR_NUM,SON_NUM,SONNAM INTO S_MAIN_NUM,S_BAR_NUM,S_NUM,S_ACT_NAME FROM CLASSACT WHERE SON_NUM=3005;
SELECT AC_NUM,BAR_NUM,SON_NUM,SONNAM INTO M_MAIN_NUM,M_BAR_NUM,M_NUM,M_ACT_NAME FROM CLASSACT WHERE SON_NUM=3006;
   IF INSERTING THEN
  IF :NEW.SI_ID=:NEW.SI_ID THEN
  Insert into account_ledger(AL_ID,AL_ACC_NO,AL_ACC_NAME,AL_DATE,AL_CREDIT_MOUNT,AL_DEPIT_MOUNT,AL_SOURCE,AL_EXP,al_doc_id,al_doc_type,al_st,AL_BAR_NUM,AL_MAIN_NUM) values((select nvl(max(al_id)+1,1) from account_ledger),:new.SI_NUM,:new.SI_CUSTOMER,:new.SI_date,:new.SI_TOTAL,0,:new.SI_status,nvl(:new.SI_NOTE,'no notes'),:new.SI_id,10,1,:NEW.SI_BAR_NUM,:NEW.SI_MAIN_NUM);
 Insert into account_ledger(AL_ID,AL_ACC_NO,AL_ACC_NAME,AL_DATE,AL_CREDIT_MOUNT,AL_DEPIT_MOUNT,AL_SOURCE,AL_EXP,al_doc_id,al_doc_type,al_st,AL_BAR_NUM,AL_MAIN_NUM) values((select nvl(max(al_id)+1,1) from account_ledger),:new.SI_BC_NUM,:new.SI_ACT_NAME,:new.SI_date,0,:new.SI_TOTAL,:new.SI_status,nvl(:new.SI_NOTE,'no notes'),:new.SI_id,10,2,:NEW.SI_BC_BAR_NUM,:NEW.SI_BC_MAIN_NUM);

  Insert into account_ledger(AL_ID,AL_ACC_NO,AL_ACC_NAME,AL_DATE,AL_CREDIT_MOUNT,AL_DEPIT_MOUNT,AL_SOURCE,AL_EXP,al_doc_id,al_doc_type,al_st,AL_BAR_NUM,AL_MAIN_NUM) values((select nvl(max(al_id)+1,1) from account_ledger),S_NUM,S_ACT_NAME,:new.SI_date,:new.SI_COST_TOTAL,0,:new.SI_status,nvl(:new.SI_NOTE,'no notes'),:new.SI_id,11,1,S_BAR_NUM,S_MAIN_NUM);
 Insert into account_ledger(AL_ID,AL_ACC_NO,AL_ACC_NAME,AL_DATE,AL_CREDIT_MOUNT,AL_DEPIT_MOUNT,AL_SOURCE,AL_EXP,al_doc_id,al_doc_type,al_st,AL_BAR_NUM,AL_MAIN_NUM) values((select nvl(max(al_id)+1,1) from account_ledger),M_NUM,M_ACT_NAME,:new.SI_date,0,:new.SI_COST_TOTAL,:new.SI_status,nvl(:new.SI_NOTE,'no notes'),:new.SI_id,11,2,M_BAR_NUM,M_MAIN_NUM);
  END IF;
  END IF;
  IF UPDATING THEN
   IF :NEW.SI_ID=:NEW.SI_ID THEN
   update account_ledger set AL_ACC_NO=:new.SI_num,AL_ACC_NAME=:new.SI_CUSTOMER,AL_DATE=:new.SI_date,AL_CREDIT_MOUNT=:new.SI_TOTAL,AL_DEPIT_MOUNT=0,AL_SOURCE=:new.SI_status,AL_EXP=NVL(:new.SI_NOTE,'NO NOTES'),AL_BAR_NUM=:NEW.SI_BAR_NUM,AL_MAIN_NUM=:NEW.SI_MAIN_NUM where al_doc_type=10 and al_doc_id=:new.SI_ID and al_st=1;
 update account_ledger set AL_ACC_NO=:new.SI_BC_num,AL_ACC_NAME=:new.SI_ACT_NAME,AL_DATE=:new.SI_date,AL_CREDIT_MOUNT=0,AL_DEPIT_MOUNT=:new.SI_TOTAL,AL_SOURCE=:new.SI_status,AL_EXP=NVL(:new.SI_NOTE,'NO NOTES'),AL_BAR_NUM=:NEW.SI_BC_BAR_NUM,AL_MAIN_NUM=:NEW.SI_BC_MAIN_NUM where al_doc_type=10 and al_doc_id=:new.SI_ID and al_st=1;
  update account_ledger set AL_ACC_NO=S_num,AL_ACC_NAME=S_ACT_NAME,AL_DATE=:new.SI_date,AL_CREDIT_MOUNT=:new.SI_COST_TOTAL,AL_DEPIT_MOUNT=0,AL_SOURCE=:new.SI_status,AL_EXP=NVL(:new.SI_NOTE,'NO NOTES'),AL_BAR_NUM=S_BAR_NUM,AL_MAIN_NUM=S_MAIN_NUM where al_doc_type=11 and al_doc_id=:new.SI_ID and al_st=1;
 update account_ledger set AL_ACC_NO=M_num,AL_ACC_NAME=M_ACT_NAME,AL_DATE=:new.SI_date,AL_CREDIT_MOUNT=0,AL_DEPIT_MOUNT=:new.SI_COST_TOTAL,AL_SOURCE=:new.SI_status,AL_EXP=NVL(:new.SI_NOTE,'NO NOTES'),AL_BAR_NUM=M_BAR_NUM,AL_MAIN_NUM=M_MAIN_NUM where al_doc_type=11 and al_doc_id=:new.SI_ID and al_st=2;

   END IF;
  END IF;
  IF DELETING THEN
  if  :old.SI_id = :old.SI_id  then
delete from  account_ledger  where al_doc_type=10 and al_doc_id=:old.SI_id;

delete from  account_ledger  where al_doc_type=11 and al_doc_id=:old.SI_id;

end  if  ;
end  if;
END;

declare
AC_NUM1 number;
AC_NAM1 varchar2(250);
BAR_NUM1 number;
main_nam varchar2(250); 
SON_NUM1 number;
SONNAM1 varchar2(250);
SONTYPE1 varchar2(100);
BEGIN
select ac_nam,ac_num into ac_nam1,ac_num1 from bransh_act where bar_num=:new.bar_num;
select ac_nam into main_nam from main_act where ac_num in(select ac_num from bransh_act where bar_num=:new.bar_num) ;
if inserting then
if :new.son_num=:new.son_num then
insert into TRAIL_BALANCE(TB_ID,tb_main_num,TB_MAIN_NAME,tb_bar_num,tb_bar_name,TB_SON_NUM,TB_SON_NAME,TB_SUM_DEPIT,TB_SUM_CREDIT,TB_DEPIT_BAL,TB_CREDIT_BAL,TB_ACT_TYPE) values((select nvl(max(tb_id)+1,1) from TRAIL_BALANCE),AC_NUM1,main_nam,:new.bar_num,AC_NAM1,:new.SON_NUM,:new.ac_NAM,0,0,0,0,:new.SON_TYPE);
end if; end if;
END;
